/**
 * @file  apps/web/lib/manual.ts
 * @area  Docs
 * @what  Reads the user manual for a site (docs/manual/manual-india.html or manual-global.html, generated by docs/manual/build.py and bundled into the image via outputFileTracingIncludes).
 */
import fs from 'node:fs';
import path from 'node:path';

/** Our own generated HTML (trusted, no user input). */
export function manualHtml(region: 'IN' | 'GLOBAL'): string {
  const file = region === 'IN' ? 'manual-india.html' : 'manual-global.html';
  for (const base of [process.cwd(), path.join(process.cwd(), '..', '..')]) {
    const p = path.join(base, 'docs', 'manual', file);
    if (fs.existsSync(p)) return fs.readFileSync(p, 'utf8');
  }
  return '<div class="mn"><p>The manual is being updated. Write to support@pnllens.com for help.</p></div>';
}
